questionvariables.text:
/*doubling time in growth*/
initial_no:(rand(20)+10)*10;
period_months:rand(4)+4;
dobled_no:initial_no*2;
dobled_no_results:rand_with_step(5000,10000,100);
/*solution variables*/
sol1:dobled_no_results=initial_no*(%e^((log(2)/period_months)*t));
sol2:(dobled_no_results/initial_no)=(%e^((log(2)/period_months)*t));
sol3:log(dobled_no_results/initial_no)=(log(2)/period_months)*t;
sol4:t=period_months*(log(dobled_no_results/initial_no)/log(2));
sol5:period_months*(log((dobled_no_results/initial_no))/log(2));
sol6:float(sol5);
ta:decimalplaces(sol6,1)
